import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState } from 'react';
import { useSettings } from './hooks/useSettings';
import SettingsPanel from './components/SettingsPanel';
import CalculatorSection from './components/CalculatorSection';

const CalculatorIcon: React.FC<React.SVGProps<SVGSVGElement>> = (props) => (
  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" {...props}>
    <rect width="16" height="20" x="4" y="2" rx="2" />
    <line x1="8" x2="16" y1="6" y2="6" />
    <line x1="16" x2="16" y1="14" y2="18" />
    <line x1="16" x2="12" y1="14" y2="14" />
    <line x1="12" x2="12" y1="14" y2="18" />
    <line x1="8" x2="8" y1="14" y2="18" />
  </svg>
);


export default function App() {
  const { settings, setSettings } = useSettings();
  const [showSettings, setShowSettings] = useState(true);

  return (
    <div className="min-h-screen bg-gray-50 text-gray-800 font-sans p-4 md:p-8">
      <div className="max-w-7xl mx-auto">
        <header className="flex items-center justify-center mb-8">
          <CalculatorIcon className="w-10 h-10 text-blue-600" />
          <h1 className="text-4xl font-bold text-gray-700 ml-4">Precifica Fácil</h1>
        </header>

        <main>
          <SettingsPanel 
            initialSettings={settings}
            onSave={setSettings}
            isOpen={showSettings}
            setIsOpen={setShowSettings}
          />
          <CalculatorSection settings={settings} />
        </main>
      </div>
    </div>
  );
}

export enum Platform {
  ML_CLASSICO = 'ML Clássico',
  ML_PREMIUM = 'ML Premium',
  SHOPEE = 'Shopee',
  TIKTOK_SHOP = 'TikTok Shop',
  INSTAGRAM = 'Instagram',
}

export interface MercadoLivreSettings {
  contributionMargin: number;
  classicCommission: number;
  premiumCommission: number;
  fixedFee: number;
  shippingFee: number;
}

export interface ShopeeSettings {
  contributionMargin: number;
  commission: number;
  fixedFee: number;
}

export interface TikTokShopSettings {
  contributionMargin: number;
  commission: number;
  shippingCommission: number;
  fixedFee: number;
}

export interface InstagramSettings {
  contributionMargin: number;
}

export interface AppSettings {
  simplesNacional: number;
  mercadoLivre: MercadoLivreSettings;
  shopee: ShopeeSettings;
  tiktok: TikTokShopSettings;
  instagram: InstagramSettings;
}

export interface CalculationResult {
  platform: Platform;
  sellingPrice?: number;
  productCost?: number;
  fixedFee: number;
  commission: number;
  tax: number;
  grossProfit: number;
  calculatedMargin: number;
  maxProductCost?: number;
}

import { useState, useEffect } from 'react';
import { AppSettings } from '../types';

const SETTINGS_KEY = 'precificaFacilSettings';

const defaultSettings: AppSettings = {
  simplesNacional: 6,
  mercadoLivre: {
    contributionMargin: 17,
    classicCommission: 14,
    premiumCommission: 19,
    fixedFee: 6.00,
    shippingFee: 24.00,
  },
  shopee: {
    contributionMargin: 17,
    commission: 20,
    fixedFee: 4.00,
  },
  tiktok: {
    contributionMargin: 15,
    commission: 6,
    shippingCommission: 6,
    fixedFee: 2.00,
  },
  instagram: {
    contributionMargin: 15,
  },
};

export function useSettings() {
  const [settings, setSettings] = useState<AppSettings>(() => {
    try {
      const storedSettings = window.localStorage.getItem(SETTINGS_KEY);
      if (storedSettings) {
        // Basic migration: merge stored settings with defaults to add new fields
        const parsedSettings = JSON.parse(storedSettings);
        return {
            ...defaultSettings,
            ...parsedSettings,
            mercadoLivre: {...defaultSettings.mercadoLivre, ...parsedSettings.mercadoLivre},
            shopee: {...defaultSettings.shopee, ...parsedSettings.shopee},
            tiktok: {...defaultSettings.tiktok, ...parsedSettings.tiktok},
            instagram: {...defaultSettings.instagram, ...parsedSettings.instagram},
        };
      }
    } catch (error) {
      console.error("Error reading settings from localStorage", error);
    }
    return defaultSettings;
  });

  useEffect(() => {
    try {
      window.localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));
    } catch (error) {
      console.error("Error saving settings to localStorage", error);
    }
  }, [settings]);

  return { settings, setSettings };
}

import { AppSettings, Platform, CalculationResult } from '../types';

const MERCADO_LIVRE_SHIPPING_THRESHOLD = 79;

export function formatCurrency(value: number | undefined | null): string {
  if (value === undefined || value === null || isNaN(value)) {
    return '---';
  }
  return value.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
}

export function formatPercentage(value: number | undefined | null): string {
    if (value === undefined || value === null || isNaN(value)) {
      return '---';
    }
    return `${value.toFixed(2)}%`;
}

function calculateSellingPrice(
  productCost: number,
  fixedCost: number,
  totalPercentage: number
): number {
  if (1 - totalPercentage <= 0) return Infinity;
  return (productCost + fixedCost) / (1 - totalPercentage);
}

export function calculateIndividualPrices(productCost: number, settings: AppSettings): CalculationResult[] {
  const results: CalculationResult[] = [];
  const taxPercent = settings.simplesNacional / 100;

  // Mercado Livre Clássico
  const mlClassicMargin = settings.mercadoLivre.contributionMargin / 100;
  const mlClassicCommission = settings.mercadoLivre.classicCommission / 100;
  let mlClassicTotalPercent = mlClassicMargin + mlClassicCommission + taxPercent;
  let tempClassicPrice = calculateSellingPrice(productCost, settings.mercadoLivre.fixedFee, mlClassicTotalPercent);

  let mlClassicFinalPrice: number;
  let mlClassicFixedFee: number;

  if (tempClassicPrice >= MERCADO_LIVRE_SHIPPING_THRESHOLD) {
    mlClassicFixedFee = settings.mercadoLivre.shippingFee;
    mlClassicFinalPrice = calculateSellingPrice(productCost, mlClassicFixedFee, mlClassicTotalPercent);
  } else {
    mlClassicFixedFee = settings.mercadoLivre.fixedFee;
    mlClassicFinalPrice = tempClassicPrice;
  }

  const mlClassicCommissionValue = mlClassicFinalPrice * mlClassicCommission;
  const mlClassicTaxValue = mlClassicFinalPrice * taxPercent;
  const mlClassicGrossProfit = mlClassicFinalPrice - productCost - mlClassicFixedFee - mlClassicCommissionValue - mlClassicTaxValue;

  results.push({
    platform: Platform.ML_CLASSICO,
    sellingPrice: mlClassicFinalPrice,
    productCost: productCost,
    fixedFee: mlClassicFixedFee,
    commission: mlClassicCommissionValue,
    tax: mlClassicTaxValue,
    grossProfit: mlClassicGrossProfit,
    calculatedMargin: (mlClassicGrossProfit / mlClassicFinalPrice) * 100,
  });

  // Mercado Livre Premium
  const mlPremiumMargin = settings.mercadoLivre.contributionMargin / 100;
  const mlPremiumCommission = settings.mercadoLivre.premiumCommission / 100;
  let mlPremiumTotalPercent = mlPremiumMargin + mlPremiumCommission + taxPercent;
  let tempPremiumPrice = calculateSellingPrice(productCost, settings.mercadoLivre.fixedFee, mlPremiumTotalPercent);

  let mlPremiumFinalPrice: number;
  let mlPremiumFixedFee: number;

  if (tempPremiumPrice >= MERCADO_LIVRE_SHIPPING_THRESHOLD) {
      mlPremiumFixedFee = settings.mercadoLivre.shippingFee;
      mlPremiumFinalPrice = calculateSellingPrice(productCost, mlPremiumFixedFee, mlPremiumTotalPercent);
  } else {
      mlPremiumFixedFee = settings.mercadoLivre.fixedFee;
      mlPremiumFinalPrice = tempPremiumPrice;
  }

  const mlPremiumCommissionValue = mlPremiumFinalPrice * mlPremiumCommission;
  const mlPremiumTaxValue = mlPremiumFinalPrice * taxPercent;
  const mlPremiumGrossProfit = mlPremiumFinalPrice - productCost - mlPremiumFixedFee - mlPremiumCommissionValue - mlPremiumTaxValue;

  results.push({
    platform: Platform.ML_PREMIUM,
    sellingPrice: mlPremiumFinalPrice,
    productCost: productCost,
    fixedFee: mlPremiumFixedFee,
    commission: mlPremiumCommissionValue,
    tax: mlPremiumTaxValue,
    grossProfit: mlPremiumGrossProfit,
    calculatedMargin: (mlPremiumGrossProfit / mlPremiumFinalPrice) * 100,
  });

  // Shopee
  const shopeeMargin = settings.shopee.contributionMargin / 100;
  const shopeeCommission = settings.shopee.commission / 100;
  const shopeeTotalPercent = shopeeMargin + shopeeCommission + taxPercent;
  const shopeePrice = calculateSellingPrice(productCost, settings.shopee.fixedFee, shopeeTotalPercent);
  const shopeeCommissionValue = shopeePrice * shopeeCommission;
  const shopeeTaxValue = shopeePrice * taxPercent;
  const shopeeGrossProfit = shopeePrice - productCost - settings.shopee.fixedFee - shopeeCommissionValue - shopeeTaxValue;
  results.push({
    platform: Platform.SHOPEE,
    sellingPrice: shopeePrice,
    productCost: productCost,
    fixedFee: settings.shopee.fixedFee,
    commission: shopeeCommissionValue,
    tax: shopeeTaxValue,
    grossProfit: shopeeGrossProfit,
    calculatedMargin: (shopeeGrossProfit / shopeePrice) * 100,
  });

  // TikTok Shop
  const tiktokMargin = settings.tiktok.contributionMargin / 100;
  const tiktokCommission = (settings.tiktok.commission + settings.tiktok.shippingCommission) / 100;
  const tiktokTotalPercent = tiktokMargin + tiktokCommission + taxPercent;
  const tiktokPrice = calculateSellingPrice(productCost, settings.tiktok.fixedFee, tiktokTotalPercent);
  const tiktokCommissionValue = tiktokPrice * tiktokCommission;
  const tiktokTaxValue = tiktokPrice * taxPercent;
  const tiktokGrossProfit = tiktokPrice - productCost - settings.tiktok.fixedFee - tiktokCommissionValue - tiktokTaxValue;
  results.push({
    platform: Platform.TIKTOK_SHOP,
    sellingPrice: tiktokPrice,
    productCost: productCost,
    fixedFee: settings.tiktok.fixedFee,
    commission: tiktokCommissionValue,
    tax: tiktokTaxValue,
    grossProfit: tiktokGrossProfit,
    calculatedMargin: (tiktokGrossProfit / tiktokPrice) * 100,
  });

  // Instagram
  const instagramMargin = settings.instagram.contributionMargin / 100;
  const instagramTotalPercent = instagramMargin + taxPercent;
  const instagramPrice = calculateSellingPrice(productCost, 0, instagramTotalPercent);
  const instagramTaxValue = instagramPrice * taxPercent;
  const instagramGrossProfit = instagramPrice - productCost - instagramTaxValue;
  results.push({
    platform: Platform.INSTAGRAM,
    sellingPrice: instagramPrice,
    productCost: productCost,
    fixedFee: 0,
    commission: 0,
    tax: instagramTaxValue,
    grossProfit: instagramGrossProfit,
    calculatedMargin: (instagramGrossProfit / instagramPrice) * 100,
  });

  return results;
}

export function calculateMaxCost(desiredPrice: number, settings: AppSettings): CalculationResult[] {
    const results: CalculationResult[] = [];
    const taxPercent = settings.simplesNacional / 100;

    const platforms = [
        Platform.ML_CLASSICO, Platform.ML_PREMIUM, Platform.SHOPEE, Platform.TIKTOK_SHOP, Platform.INSTAGRAM
    ];

    platforms.forEach(platform => {
        let commissionPercent = 0;
        let fixedFee = 0;
        let marginPercent = 0;

        switch (platform) {
            case Platform.ML_CLASSICO:
                commissionPercent = settings.mercadoLivre.classicCommission / 100;
                fixedFee = desiredPrice < MERCADO_LIVRE_SHIPPING_THRESHOLD ? settings.mercadoLivre.fixedFee : settings.mercadoLivre.shippingFee;
                marginPercent = settings.mercadoLivre.contributionMargin / 100;
                break;
            case Platform.ML_PREMIUM:
                commissionPercent = settings.mercadoLivre.premiumCommission / 100;
                fixedFee = desiredPrice < MERCADO_LIVRE_SHIPPING_THRESHOLD ? settings.mercadoLivre.fixedFee : settings.mercadoLivre.shippingFee;
                marginPercent = settings.mercadoLivre.contributionMargin / 100;
                break;
            case Platform.SHOPEE:
                commissionPercent = settings.shopee.commission / 100;
                fixedFee = settings.shopee.fixedFee;
                marginPercent = settings.shopee.contributionMargin / 100;
                break;
            case Platform.TIKTOK_SHOP:
                commissionPercent = (settings.tiktok.commission + settings.tiktok.shippingCommission) / 100;
                fixedFee = settings.tiktok.fixedFee;
                marginPercent = settings.tiktok.contributionMargin / 100;
                break;
            case Platform.INSTAGRAM:
                commissionPercent = 0;
                fixedFee = 0;
                marginPercent = settings.instagram.contributionMargin / 100;
                break;
        }

        const commissionValue = desiredPrice * commissionPercent;
        const taxValue = desiredPrice * taxPercent;
        const profitValue = desiredPrice * marginPercent;
        const maxCost = desiredPrice - fixedFee - commissionValue - taxValue - profitValue;

        results.push({
            platform,
            sellingPrice: desiredPrice,
            maxProductCost: maxCost,
            fixedFee,
            commission: commissionValue,
            tax: taxValue,
            grossProfit: profitValue,
            calculatedMargin: marginPercent * 100,
        });
    });

    return results;
}

export function simulateMargin(productCost: number, sellingPrice: number, settings: AppSettings): CalculationResult[] {
    const results: CalculationResult[] = [];
    const taxPercent = settings.simplesNacional / 100;

    const platforms = [
        Platform.ML_CLASSICO, Platform.ML_PREMIUM, Platform.SHOPEE, Platform.TIKTOK_SHOP, Platform.INSTAGRAM
    ];

    platforms.forEach(platform => {
        let commissionPercent = 0;
        let fixedFee = 0;

        switch (platform) {
            case Platform.ML_CLASSICO:
                commissionPercent = settings.mercadoLivre.classicCommission / 100;
                fixedFee = sellingPrice < MERCADO_LIVRE_SHIPPING_THRESHOLD ? settings.mercadoLivre.fixedFee : settings.mercadoLivre.shippingFee;
                break;
            case Platform.ML_PREMIUM:
                commissionPercent = settings.mercadoLivre.premiumCommission / 100;
                fixedFee = sellingPrice < MERCADO_LIVRE_SHIPPING_THRESHOLD ? settings.mercadoLivre.fixedFee : settings.mercadoLivre.shippingFee;
                break;
            case Platform.SHOPEE:
                commissionPercent = settings.shopee.commission / 100;
                fixedFee = settings.shopee.fixedFee;
                break;
            case Platform.TIKTOK_SHOP:
                commissionPercent = (settings.tiktok.commission + settings.tiktok.shippingCommission) / 100;
                fixedFee = settings.tiktok.fixedFee;
                break;
            case Platform.INSTAGRAM:
                commissionPercent = 0;
                fixedFee = 0;
                break;
        }

        const commissionValue = sellingPrice * commissionPercent;
        const taxValue = sellingPrice * taxPercent;
        const grossProfit = sellingPrice - productCost - fixedFee - commissionValue - taxValue;
        const calculatedMargin = sellingPrice > 0 ? (grossProfit / sellingPrice) * 100 : 0;

        results.push({
            platform,
            productCost,
            sellingPrice,
            fixedFee,
            commission: commissionValue,
            tax: taxValue,
            grossProfit,
            calculatedMargin,
        });
    });

    return results;
}

import React, { useState } from 'react';
import type { AppSettings } from '../types';

interface SettingsPanelProps {
  initialSettings: AppSettings;
  onSave: (settings: AppSettings) => void;
  isOpen: boolean;
  setIsOpen: (isOpen: boolean) => void;
}

const SettingsCard: React.FC<React.PropsWithChildren<{ title: string; color: string }>> = ({ title, color, children }) => (
  <div className={`${color} p-6 rounded-lg shadow-md`}>
    <h3 className="text-xl font-bold text-gray-700 mb-4">{title}</h3>
    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
      {children}
    </div>
  </div>
);

const InputField: React.FC<{ label: string; value: number; onChange: (e: React.ChangeEvent<HTMLInputElement>) => void; isCurrency?: boolean }> = ({ label, value, onChange, isCurrency = false }) => (
  <div>
    <label className="block text-sm font-medium text-gray-600">{label}</label>
    <div className="mt-1 relative rounded-md shadow-sm">
      <div className="pointer-events-none absolute inset-y-0 left-0 pl-3 flex items-center">
        <span className="text-gray-500 sm:text-sm">{isCurrency ? 'R$' : '%'}</span>
      </div>
      <input
        type="number"
        step="0.01"
        value={value}
        onChange={onChange}
        className="block w-full rounded-md border-gray-300 pl-10 pr-4 py-2 focus:border-blue-500 focus:ring-blue-500 sm:text-sm"
      />
    </div>
  </div>
);


export default function SettingsPanel({ initialSettings, onSave, isOpen, setIsOpen }: SettingsPanelProps) {
  const [settings, setSettings] = useState<AppSettings>(initialSettings);

  const handleSave = () => {
    onSave(settings);
    alert('Configurações salvas com sucesso!');
  };

  const handleInputChange = (section: keyof AppSettings, field: string, value: string) => {
    const numericValue = parseFloat(value) || 0;
    setSettings(prev => {
        const updatedSection = { ...prev[section], [field]: numericValue };
        return { ...prev, [section]: updatedSection };
    });
  };

  const handleGeneralChange = (field: keyof AppSettings, value: string) => {
     const numericValue = parseFloat(value) || 0;
     setSettings(prev => ({...prev, [field]: numericValue }));
  }

  if (!isOpen) {
    return (
        <div className="text-center mb-6">
            <button
            onClick={() => setIsOpen(true)}
            className="px-6 py-2 bg-gray-200 text-gray-700 font-semibold rounded-lg hover:bg-gray-300 transition-colors"
            >
            Mostrar Configurações
            </button>
        </div>
    );
  }

  return (
    <div className="bg-white p-6 rounded-xl shadow-lg mb-8 border border-gray-200">
      <div className="flex justify-between items-center mb-4">
        <h2 className="text-2xl font-bold text-gray-800">Parâmetros Específicos por Plataforma e Gerais</h2>
        <button
          onClick={() => setIsOpen(false)}
          className="text-gray-500 hover:text-gray-800"
        >
          <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>
        </button>
      </div>

      <div className="space-y-6">
        <div className="bg-gray-100 p-6 rounded-lg">
           <h3 className="text-xl font-bold text-gray-700 mb-4">Imposto Geral</h3>
            <InputField
              label="Simples Nacional (%):"
              value={settings.simplesNacional}
              onChange={(e) => handleGeneralChange('simplesNacional', e.target.value)}
            />
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 xl:grid-cols-4 gap-6">
          <SettingsCard title="Mercado Livre" color="bg-yellow-100">
            <InputField label="Margem Contribuição ML (%):" value={settings.mercadoLivre.contributionMargin} onChange={(e) => handleInputChange('mercadoLivre', 'contributionMargin', e.target.value)} />
            <InputField label="Comissão Anúncio Clássico (%):" value={settings.mercadoLivre.classicCommission} onChange={(e) => handleInputChange('mercadoLivre', 'classicCommission', e.target.value)} />
            <InputField label="Comissão Anúncio Premium (%):" value={settings.mercadoLivre.premiumCommission} onChange={(e) => handleInputChange('mercadoLivre', 'premiumCommission', e.target.value)} />
            <InputField label="Taxa Fixa Produtos abaixo de R$ 79,00:" value={settings.mercadoLivre.fixedFee} onChange={(e) => handleInputChange('mercadoLivre', 'fixedFee', e.target.value)} isCurrency/>
            <InputField label="Valor Frete Grátis Pago pelo Vendedor:" value={settings.mercadoLivre.shippingFee} onChange={(e) => handleInputChange('mercadoLivre', 'shippingFee', e.target.value)} isCurrency/>
          </SettingsCard>

          <SettingsCard title="Shopee" color="bg-rose-100">
            <InputField label="Margem Contribuição Shopee (%):" value={settings.shopee.contributionMargin} onChange={(e) => handleInputChange('shopee', 'contributionMargin', e.target.value)} />
            <InputField label="Comissão Shopee (%):" value={settings.shopee.commission} onChange={(e) => handleInputChange('shopee', 'commission', e.target.value)} />
            <InputField label="Taxa Fixa Shopee:" value={settings.shopee.fixedFee} onChange={(e) => handleInputChange('shopee', 'fixedFee', e.target.value)} isCurrency/>
          </SettingsCard>

          <SettingsCard title="TikTok Shop" color="bg-gray-200">
            <InputField label="Margem Contribuição TikTok (%):" value={settings.tiktok.contributionMargin} onChange={(e) => handleInputChange('tiktok', 'contributionMargin', e.target.value)} />
            <InputField label="Comissão Fixa (%):" value={settings.tiktok.commission} onChange={(e) => handleInputChange('tiktok', 'commission', e.target.value)} />
            <InputField label="Comissão Frete Grátis (%):" value={settings.tiktok.shippingCommission} onChange={(e) => handleInputChange('tiktok', 'shippingCommission', e.target.value)} />
            <InputField label="Taxas Adicionais:" value={settings.tiktok.fixedFee} onChange={(e) => handleInputChange('tiktok', 'fixedFee', e.target.value)} isCurrency/>
          </SettingsCard>

          <SettingsCard title="Instagram" color="bg-blue-100">
            <InputField label="Margem Contribuição Instagram (%):" value={settings.instagram.contributionMargin} onChange={(e) => handleInputChange('instagram', 'contributionMargin', e.target.value)} />
          </SettingsCard>
        </div>

        <div className="flex justify-start pt-4">
          <button onClick={handleSave} className="bg-blue-600 text-white font-bold py-3 px-6 rounded-lg hover:bg-blue-700 transition-colors shadow-md">
            Salvar Configurações
          </button>
        </div>
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import type { AppSettings, CalculationResult } from '../types';
import { 
    calculateIndividualPrices, 
    calculateMaxCost, 
    simulateMargin,
    formatCurrency,
    formatPercentage
} from '../lib/calculator';

interface CalculatorSectionProps {
  settings: AppSettings;
}

const Card: React.FC<React.PropsWithChildren<{ title: string }>> = ({ title, children }) => (
    <div className="bg-white p-6 rounded-xl shadow-lg mb-8 border border-gray-200">
        <h2 className="text-2xl font-bold text-gray-800 mb-6 border-b pb-4">{title}</h2>
        {children}
    </div>
);

const ResultsTable: React.FC<{ results: CalculationResult[]; headers: string[] }> = ({ results, headers }) => {
    if (!results.length) {
        return <div className="text-center text-gray-500 py-8">Preencha os campos e clique em calcular para ver os resultados.</div>;
    }

    return (
        <div className="overflow-x-auto mt-6">
            <table className="min-w-full divide-y divide-gray-200">
                <thead className="bg-gray-100">
                    <tr>
                        {headers.map(header => (
                            <th key={header} scope="col" className="px-4 py-3 text-left text-xs font-bold text-gray-600 uppercase tracking-wider">
                                {header}
                            </th>
                        ))}
                    </tr>
                </thead>
                <tbody className="bg-white divide-y divide-gray-200">
                    {results.map(res => (
                        <tr key={res.platform} className="hover:bg-gray-50">
                            <td className="px-4 py-4 whitespace-nowrap text-sm font-medium text-gray-900">{res.platform}</td>
                            {headers.includes('Preço de Venda (R$)') && <td className="px-4 py-4 whitespace-nowrap text-sm text-gray-700">{formatCurrency(res.sellingPrice)}</td>}
                            {headers.includes('Custo Produto (R$)') && <td className="px-4 py-4 whitespace-nowrap text-sm text-gray-700">{formatCurrency(res.productCost)}</td>}
                            {headers.includes('Taxa Fixa (R$)') && <td className="px-4 py-4 whitespace-nowrap text-sm text-gray-700">{formatCurrency(res.fixedFee)}</td>}
                            {headers.includes('Comissão (R$)') && <td className="px-4 py-4 whitespace-nowrap text-sm text-gray-700">{formatCurrency(res.commission)}</td>}
                            {headers.includes('Imposto SN (R$)') && <td className="px-4 py-4 whitespace-nowrap text-sm text-gray-700">{formatCurrency(res.tax)}</td>}
                            {headers.includes('Lucro Bruto (R$)') && <td className="px-4 py-4 whitespace-nowrap text-sm text-green-700 font-semibold">{formatCurrency(res.grossProfit)}</td>}
                            {headers.includes('Margem Calculada (%)') && <td className="px-4 py-4 whitespace-nowrap text-sm text-blue-700 font-semibold">{formatPercentage(res.calculatedMargin)}</td>}
                            {headers.includes('Custo Máximo do Produto (R$)') && <td className="px-4 py-4 whitespace-nowrap text-sm text-green-700 font-semibold">{formatCurrency(res.maxProductCost)}</td>}
                        </tr>
                    ))}
