                                <span className={isNegative ? 'text-red-700' : 'text-blue-700'}>Margem Final</span>
                                <span className={isNegative ? 'text-red-700' : 'text-blue-700'}>{formatPercentage(res.calculatedMargin)}</span>
                            </div>
