import { useState, useEffect, useCallback } from 'react';

const ACCESS_KEY = 'precificaAccess';
const EXPIRATION_KEY = 'precificaExpiration';
const TEST_CODE_KEY = 'precificaTestCode';
const TEST_CODE_EXPIRATION_KEY = 'precificaTestCodeExpiration';


type AccessLevel = 'restricted' | 'full';

// Access codes and their duration in hours
const CODES: Record<string, number> = {
  'TESTE-24H': 24,
  'PRO-ANUAL': 365 * 24,
};

export function useAccess() {
  const [accessLevel, setAccessLevel] = useState<AccessLevel>('restricted');
  const [expiration, setExpiration] = useState<number | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [message, setMessage] = useState<string>('');

  useEffect(() => {
    try {
      const storedAccess = window.localStorage.getItem(ACCESS_KEY);
      const storedExpiration = window.localStorage.getItem(EXPIRATION_KEY);

      if (storedAccess === 'full' && storedExpiration) {
        const expirationTimestamp = parseInt(storedExpiration, 10);
        if (Date.now() < expirationTimestamp) {
          setAccessLevel('full');
          setExpiration(expirationTimestamp);
        } else {
          // Access has expired
          window.localStorage.removeItem(ACCESS_KEY);
          window.localStorage.removeItem(EXPIRATION_KEY);
          setAccessLevel('restricted');
          setExpiration(null);
          setMessage('Seu período de acesso expirou. Ative novamente para continuar usando todos os recursos.');
        }
      }
    } catch (error) {
      console.error("Error reading access state from localStorage", error);
    } finally {
      setIsLoading(false);
    }
  }, []);

  const activate = useCallback(async (code: string): Promise<{ success: boolean; message?: string }> => {
    const upperCaseCode = code.toUpperCase();
    const hours = CODES[upperCaseCode];

    // Check for static codes first
    if (hours) {
      try {
        const expirationTimestamp = Date.now() + hours * 60 * 60 * 1000;
        window.localStorage.setItem(ACCESS_KEY, 'full');
        window.localStorage.setItem(EXPIRATION_KEY, expirationTimestamp.toString());
        setAccessLevel('full');
        setExpiration(expirationTimestamp);
        setMessage('');
        return { success: true };
      } catch (error) {
        console.error("Error saving access state to localStorage", error);
        return { success: false, message: 'Ocorreu um erro ao salvar o acesso.' };
      }
    }

    // If not a static code, check for a temporary test code
    try {
      const storedTestCode = window.localStorage.getItem(TEST_CODE_KEY);
      const storedTestCodeExpiration = window.localStorage.getItem(TEST_CODE_EXPIRATION_KEY);

      if (storedTestCode && storedTestCodeExpiration && upperCaseCode === storedTestCode.toUpperCase()) {
        const expirationTimestamp = parseInt(storedTestCodeExpiration, 10);

        if (Date.now() < expirationTimestamp) {
          // Valid test code. Activate full access for 10 minutes from now.
          const accessDuration = 10 * 60 * 1000; // 10 minutes in ms
          const accessExpirationTimestamp = Date.now() + accessDuration;

          window.localStorage.setItem(ACCESS_KEY, 'full');
          window.localStorage.setItem(EXPIRATION_KEY, accessExpirationTimestamp.toString());

          // Clean up the used test code so it cannot be used again
          window.localStorage.removeItem(TEST_CODE_KEY);
          window.localStorage.removeItem(TEST_CODE_EXPIRATION_KEY);

          setAccessLevel('full');
          setExpiration(accessExpirationTimestamp);
          setMessage('');
          return { success: true };
        } else {
          // Test code has expired
          window.localStorage.removeItem(TEST_CODE_KEY);
          window.localStorage.removeItem(TEST_CODE_EXPIRATION_KEY);
          return { success: false, message: 'Seu código de teste expirou.' };
        }
      }
    } catch (error) {
        console.error("Error reading test code from localStorage", error);
        return { success: false, message: 'Ocorreu um erro ao validar o código.' };
    }

    // If no valid code was found
    return { success: false, message: 'Código de acesso inválido.' };
  }, []);

  return { accessLevel, expiration, isLoading, activate, message };
}

