const ActivationBar: React.FC<{
  activate: (code: string) => Promise<{ success: boolean; message?: string }>;
  accessMessage: string;
}> = ({ activate, accessMessage }) => {
    const [code, setCode] = useState('');
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');
    const [success, setSuccess] = useState('');
    const [generatedCode, setGeneratedCode] = useState<{code: string, expires: number} | null>(null);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');
        setSuccess('');
        setLoading(true);
        const result = await activate(code);
        if (result.success) {
            setSuccess('Acesso completo ativado com sucesso!');
            setGeneratedCode(null); // Clear test code after successful activation
        } else {
            setError(result.message || 'Ocorreu um erro.');
        }
        setLoading(false);
    };

    const generateTestCode = () => {
        const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
        let part1 = '';
        let part2 = '';
        for (let i = 0; i < 4; i++) {
          part1 += chars.charAt(Math.floor(Math.random() * chars.length));
          part2 += chars.charAt(Math.floor(Math.random() * chars.length));
        }
        const code = `PF-${part1}-${part2}`;
        const expiration = Date.now() + 5 * 60 * 1000; // 5 minutes from now

        try {
          window.localStorage.setItem('precificaTempCode', code);
          window.localStorage.setItem('precificaTempCodeExpiration', expiration.toString());
          setGeneratedCode({ code, expires: expiration });
          setError('');
          setSuccess('');
        } catch (e) {
          setError("Não foi possível gerar o código de teste.");
          console.error("Failed to save temp code to localStorage", e);
        }
    };

    return (
        <div className="bg-blue-50 border border-blue-200 p-4 rounded-lg mb-8 text-center">
