import { useState, useEffect, useCallback } from 'react';

const ACCESS_KEY = 'precificaAccess';
const EXPIRATION_KEY = 'precificaExpiration';
const TEMP_CODE_KEY = 'precificaTempCode';
const TEMP_CODE_EXPIRATION_KEY = 'precificaTempCodeExpiration';


type AccessLevel = 'restricted' | 'full';

// Access codes and their duration in hours
const CODES: Record<string, number> = {
  'TESTE-24H': 24,
  'PRO-ANUAL': 365 * 24,
};

export function useAccess() {
  const [accessLevel, setAccessLevel] = useState<AccessLevel>('restricted');
  const [expiration, setExpiration] = useState<number | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [message, setMessage] = useState<string>('');

  useEffect(() => {
    try {
      const storedAccess = window.localStorage.getItem(ACCESS_KEY);
      const storedExpiration = window.localStorage.getItem(EXPIRATION_KEY);

      if (storedAccess === 'full' && storedExpiration) {
        const expirationTimestamp = parseInt(storedExpiration, 10);
        if (Date.now() < expirationTimestamp) {
          setAccessLevel('full');
          setExpiration(expirationTimestamp);
        } else {
          // Access has expired
          window.localStorage.removeItem(ACCESS_KEY);
          window.localStorage.removeItem(EXPIRATION_KEY);
          setAccessLevel('restricted');
          setExpiration(null);
          setMessage('Seu período de acesso expirou. Ative novamente para continuar usando todos os recursos.');
        }
      }
    } catch (error) {
      console.error("Error reading access state from localStorage", error);
    } finally {
      setIsLoading(false);
    }
  }, []);

  const activate = useCallback(async (code: string): Promise<{ success: boolean; message?: string }> => {
    const upperCaseCode = code.toUpperCase();
    const hours = CODES[upperCaseCode];

    // Check for static codes first
    if (hours) {
      try {
        const expirationTimestamp = Date.now() + hours * 60 * 60 * 1000;
        window.localStorage.setItem(ACCESS_KEY, 'full');
        window.localStorage.setItem(EXPIRATION_KEY, expirationTimestamp.toString());
        setAccessLevel('full');
        setExpiration(expirationTimestamp);
        setMessage('');
        return { success: true };
      } catch (error) {
        console.error("Error saving access state to localStorage", error);
        return { success: false, message: 'Ocorreu um erro ao salvar o acesso.' };
      }
    }

    // If not a static code, check for a temporary test code
    try {
      const storedTestCode = window.localStorage.getItem(TEMP_CODE_KEY);
      const storedTestCodeExpiration = window.localStorage.getItem(TEMP_CODE_EXPIRATION_KEY);

      if (storedTestCode && storedTestCodeExpiration && upperCaseCode === storedTestCode.toUpperCase()) {
        const expirationTimestamp = parseInt(storedTestCodeExpiration, 10);

        if (Date.now() < expirationTimestamp) {
          // Valid test code.
          window.localStorage.setItem(ACCESS_KEY, 'full');
          window.localStorage.setItem(EXPIRATION_KEY, expirationTimestamp.toString());

          // Clean up the used test code so it cannot be used again
          window.localStorage.removeItem(TEMP_CODE_KEY);
          window.localStorage.removeItem(TEMP_CODE_EXPIRATION_KEY);

          setAccessLevel('full');
          setExpiration(expirationTimestamp);
          setMessage('');
          return { success: true };
        } else {
          // Test code has expired
          window.localStorage.removeItem(TEMP_CODE_KEY);
          window.localStorage.removeItem(TEMP_CODE_EXPIRATION_KEY);
          return { success: false, message: 'Seu código de teste expirou.' };
        }
      }
    } catch (error) {
        console.error("Error reading test code from localStorage", error);
        return { success: false, message: 'Ocorreu um erro ao validar o código.' };
    }


    // If no valid code was found
    return { success: false, message: 'Código de acesso inválido.' };
  }, []);

  return { accessLevel, expiration, isLoading, activate, message };
}

import React, { useState, useEffect } from 'react';
import { AppSettings, CalculationResult, Platform } from '../types';
import { 
    calculateIndividualPrices, 
    calculateMaxCost, 
    simulateMargin,
    formatCurrency,
    formatPercentage
} from '../lib/calculator';
import { getMarketplaceIcon } from './MarketplaceIcons';
import { Lock, AlertTriangle, KeyRound } from 'lucide-react';

interface CalculatorSectionProps {
  settings: AppSettings;
  accessLevel: 'restricted' | 'full';
  activate: (code: string) => Promise<{ success: boolean; message?: string }>;
  expiration: number | null;
  accessMessage: string;
}

const ActivationBar: React.FC<{
  activate: (code: string) => Promise<{ success: boolean; message?: string }>;
  accessMessage: string;
}> = ({ activate, accessMessage }) => {
    const [code, setCode] = useState('');
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');
    const [success, setSuccess] = useState('');

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');
        setSuccess('');
        setLoading(true);
        const result = await activate(code);
        if (result.success) {
            setSuccess('Acesso completo ativado com sucesso!');
        } else {
            setError(result.message || 'Ocorreu um erro.');
        }
        setLoading(false);
    };

    return (
        <div className="bg-blue-50 border border-blue-200 p-4 rounded-lg mb-8 text-center">
            <div className="flex flex-wrap items-center justify-center gap-x-4 gap-y-2">
                <div className="flex items-center gap-2 text-blue-800 font-semibold">
                    <KeyRound className="w-5 h-5" />
                    <span>Acesso completo desativado.</span>
                </div>
                <form onSubmit={handleSubmit} className="flex items-center gap-2">
                    <input
                        type="text"
                        value={code}
                        onChange={(e) => setCode(e.target.value)}
                        placeholder="Insira seu código"
                        className="rounded-md border-gray-300 shadow-sm sm:text-sm p-2 bg-white text-gray-900 w-48"
                        aria-label="Código de Acesso"
                    />
                    <button
                        type="submit"
                        disabled={loading}
                        className="bg-blue-600 text-white font-bold py-2 px-3 rounded-lg hover:bg-blue-700 transition-colors disabled:bg-blue-300 text-sm"
                    >
                        {loading ? '...' : 'Ativar'}
                    </button>
                </form>
            </div>
             <div className="mt-2 text-sm h-5">
                 {error && <p className="text-red-600">{error}</p>}
                 {success && <p className="text-green-600">{success}</p>}
                 {accessMessage && !success && <p className="text-yellow-800">{accessMessage}</p>}
            </div>
        </div>
    );
};

