    /**
     * Iteratively calculates the final selling price for Shopee.
     */
    function calculateShopeePrice(
      productCost: number,
      settings: AppSettings
    ): {
      finalPrice: number;
      profit: number;
      profitMargin: number;
      shopeeFee: number;
      simplesNacionalFee: number;
    } {
      // FIX: Corrected typo from shpee to shopee.
      const taxPercent = settings.simplesNacional / 100;
      let finalPrice = productCost;
      let shopeeFee = 0;
      let simplesNacionalFee = 0;
      let profit = 0;
      let profitMargin = 0;
      let lastFinalPrice = 0;

      // Iterative calculation to handle Shopee fees and taxes
      do {
        lastFinalPrice = finalPrice;
        shopeeFee = finalPrice * (settings.shopeeFee / 100);
        simplesNacionalFee = finalPrice * taxPercent;
        finalPrice = productCost + shopeeFee + simplesNacionalFee;
      } while (Math.abs(finalPrice - lastFinalPrice) > 0.01);

      profit = finalPrice - productCost - shopeeFee - simplesNacionalFee;
      profitMargin = (profit / finalPrice) * 100;

      return {
        finalPrice,
        profit,
        profitMargin,
        shopeeFee,
        simplesNacionalFee,
      };
    }

