const SETTINGS_KEY = 'precificaFacilSettings';

const defaultSettings: AppSettings = {
  simplesNacional: 4,
  mercadoLivre: {
    contributionMargin: 17,
    classicCommission: 14,
    premiumCommission: 19,
    productWeight: 1,
  },
  shopee: {
    contributionMargin: 17,
    sellerType: 'cnpj',
    highVolumeCPF: false,
    inCampaign: false,
  },
  tiktok: {
    contributionMargin: 15,
    commission: 6,
    shippingCommission: 6,
    fixedFee: 2.00,
  },
